172	const freeze = <T>(value: T): Readonly<T> => {
173	  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
174	    Object.freeze(value);
175	    for (const nested of Object.values(value)) freeze(nested);
176	  }
177	  return value;
178	};
179	
180	const isNonEmptyString = (value: unknown): value is string => typeof value === 'string' && value.length > 0;
181	
182	const isPauseReason = (value: unknown): value is QueuePauseReason =>
183	  value === 'failure' || value === 'manual' || value === 'recovered_interrupted';
184	
185	const isValidPreflightKind = (value: unknown): value is PreflightKind =>
186	  value === 'input_surge' || value === 'large_uncached_input';
187	
188	const isValidActiveActionKind = (value: unknown): value is ActiveActionKind =>
189	  value === 'tool_approval' || value === 'ask_user';
190	
191	const isPersistedQueueItem = (value: unknown): value is PersistedQueueItem => {
192	  if (!value || typeof value !== 'object') return false;
193	  const item = value as Record<string, unknown>;
194	  if (
195	    !isNonEmptyString(item.id) ||
196	    typeof item.text !== 'string' ||
197	    !Number.isSafeInteger(item.sequence) ||
198	    (item.sequence as number) <= 0 ||
199	    !isNonEmptyString(item.submittedAt) ||
200	    Number.isNaN(Date.parse(item.submittedAt as string)) ||
201	    (item.steer !== undefined && typeof item.steer !== 'boolean')
202	  ) {
203	    return false;
204	  }
205	  if (item.preflight !== undefined) {
206	    if (
207	      !item.preflight ||
208	      typeof item.preflight !== 'object' ||
209	      !isNonEmptyString((item.preflight as Record<string, unknown>).actionId) ||
210	      !isValidPreflightKind((item.preflight as Record<string, unknown>).kind)
211	    ) {
212	      return false;
213	    }
214	  }
215	  return true;
216	};
217	
218	const validatePersistedQueue = <Snapshot>(value: unknown): PersistedQueueV1<Snapshot> | string => {
219	  if (!value || typeof value !== 'object') return 'record must be an object';
220	  const record = value as Record<string, unknown>;
221	  if (record.version !== 1) return 'unsupported queue record version';
222	  if (!Number.isSafeInteger(record.nextSequence) || (record.nextSequence as number) < 1) return 'invalid next sequence';
223	  if (!Array.isArray(record.queue) || !(record.queue as unknown[]).every(isPersistedQueueItem))
224	    return 'invalid queued item';
225	  const queue = record.queue as PersistedQueueItem[];
226	  if (queue.some((item, index) => index > 0 && item.sequence <= queue[index - 1]!.sequence)) {
227	    return 'queue sequences must be strictly increasing';
228	  }
229	  if (queue.some((item) => item.sequence >= (record.nextSequence as number)))
230	    return 'next sequence must exceed queue sequences';
231	  if (new Set(queue.map((item) => item.id)).size !== queue.length) return 'queue item IDs must be unique';
232	  if (record.pause !== undefined) {
233	    if (
234	      !record.pause ||
235	      typeof record.pause !== 'object' ||
236	      !isPauseReason((record.pause as Record<string, unknown>).reason)
237	    ) {
238	      return 'invalid pause record';
239	    }
240	  }
241	  if (record.active !== undefined) {
242	    if (!record.active || typeof record.active !== 'object') return 'invalid active record';
243	    const active = record.active as Record<string, unknown>;
244	    if (!isNonEmptyString(active.executionId) || !isPersistedQueueItem(active.item) || !('snapshot' in active))
245	      return 'invalid active ownership';
246	    if (!['running', 'awaiting_active_action', 'cancelling', 'completing'].includes(active.phase as string))
247	      return 'invalid active phase';
248	    if (active.pendingAction !== undefined) {
249	      if (
250	        !active.pendingAction ||
251	        typeof active.pendingAction !== 'object' ||
252	        !isNonEmptyString((active.pendingAction as Record<string, unknown>).actionId) ||
253	        !isValidActiveActionKind((active.pendingAction as Record<string, unknown>).kind)
254	      ) {
255	        return 'invalid active action';
256	      }
257	    }
258	    if (queue.some((item) => item.id === (active.item as PersistedQueueItem).id)) return 'active item is also queued';
259	  }
260	  return value as PersistedQueueV1<Snapshot>;
261	};
262	
263	const persistedItemToQueueItem = (item: PersistedQueueItem): QueueItem =>
264	  freeze({
265	    ...item,
266	    id: item.id as ItemId,
267	    preflight: item.preflight
268	      ? { actionId: item.preflight.actionId as ActionId, kind: item.preflight.kind }
269	      : undefined,
270	  });
271	
272	const queueItemToPersisted = (item: QueueItem): PersistedQueueItem => ({
273	  id: item.id,
274	  text: item.text,
275	  sequence: item.sequence,
276	  submittedAt: item.submittedAt,
277	  ...(item.steer ? { steer: true } : {}),
278	  preflight: item.preflight ? { actionId: item.preflight.actionId, kind: item.preflight.kind } : undefined,
279	});
