290	export class QueueController<Snapshot, Terminal = unknown> {

   290	export class QueueController<Snapshot, Terminal = unknown> {
   291	  readonly #driver: QueueTurnDriver<Snapshot>;
   292	  readonly #snapshotFactory: (item: QueueItem) => Snapshot;
   293	  readonly #capacity: number;
   294	  readonly #itemId: () => string;
   295	  readonly #executionId: () => string;
   296	  readonly #actionId: () => string;
   297	  readonly #now: () => string;
   298	  readonly #completionBarrier?: (event: Extract<TurnEvent<Terminal>, { kind: 'completed' }>) => void | Promise<void>;
   299	  readonly #persistence?: QueuePersistence<Snapshot>;
   300	  readonly #preflightEvaluator?: (item: QueueItem) => { preflight: { actionId: ActionId; kind: PreflightKind } } | null;
   301	  #nextSequence = 1;
   302	  #queue: QueueItem[] = [];
   303	  #phase: InternalPhase = 'idle';
   304	  #active: ActiveExecution<Snapshot> | undefined;
   305	  #pendingAction: { actionId: ActionId; kind: ActiveActionKind } | undefined;
   306	  #pauseReason: QueuePauseReason | undefined;
   307	  #recovery: QueueRecovery | undefined;
   308	  #persistenceWrites = Promise.resolve();
   309	  /** Out-of-band occupancy (manual compaction) that must not start queued work. */
   310	  #dispatchHeld = false;
   311	  #cancellationUnproven = false;
   312	  #cancellationExecutionId: ExecutionId | null = null;
   313	  #cancelRetainedItemIds = new Set<ItemId>();
   314	
   315	  constructor(options: QueueControllerOptions<Snapshot, Terminal>) {
   316	    this.#driver = options.driver;
   317	    this.#snapshotFactory = options.snapshotFactory;
   318	    this.#capacity = options.capacity ?? Infinity;
   319	    this.#itemId = options.ids?.item ?? (() => crypto.randomUUID());
   320	    this.#executionId = options.ids?.execution ?? (() => crypto.randomUUID());
   321	    this.#actionId = options.ids?.action ?? (() => crypto.randomUUID());
   322	    this.#now = options.now ?? (() => new Date().toISOString());
   323	    this.#completionBarrier = options.completionBarrier;
   324	    this.#persistence = options.persistence;
   325	    this.#preflightEvaluator = options.preflightEvaluator;
   326	    this.#restore();
   327	  }
   328	
   329	  /**
   330	   * Prevent `#dispatch` while idle. Submissions still enqueue. Returns false
   331	   * when the queue is already occupied (running, paused, or already held).
   332	   */
   333	  holdDispatch(): boolean {
   334	    if (this.#dispatchHeld || this.#phase !== 'idle' || this.#active) return false;
   335	    this.#dispatchHeld = true;
   336	    return true;
   337	  }
   338	
   339	  isDispatchHeld(): boolean {
   340	    return this.#dispatchHeld;
   341	  }
   342	
   343	  /**
   344	   * Drop the hold. By default the next queued item starts. `pauseIfQueued`
   345	   * matches stop-during-a-turn: retained work stays paused instead of running.
   346	   */
   347	  releaseDispatch(options: { pauseIfQueued?: boolean } = {}): void {
   348	    if (!this.#dispatchHeld) return;
   349	    this.#dispatchHeld = false;
   350	    if (options.pauseIfQueued && this.#queue.length > 0 && this.#phase === 'idle' && !this.#active) {
   351	      this.#phase = 'paused';
   352	      this.#pauseReason = 'manual';
   353	      void this.#persist();
   354	      return;
   355	    }
   356	    void this.#dispatch();
   357	  }
   358	
   359	  state(): QueueState<Snapshot> {
   360	    const queue = this.#queue.map((item) => ({ ...item }));
   361	    const recovery = this.#recovery ? { recovery: this.#recovery } : {};
   362	
   363	    if (this.#phase === 'awaiting_preflight') {
   364	      return freeze({
   365	        kind: 'awaiting_preflight',
   366	        queue,
   367	        head: { ...queue[0]! },
   368	        ...recovery,
   369	      });
   370	    }
   371	    if (this.#phase === 'awaiting_active_action') {
   372	      return freeze({
   373	        kind: 'awaiting_active_action',
   374	        queue,
   375	        active: this.#active!,
   376	        pendingAction: this.#pendingAction!,
   377	        ...recovery,
   378	      });
   379	    }
   380	    if (this.#phase === 'paused') return freeze({ kind: 'paused', queue, reason: this.#pauseReason!, ...recovery });
   381	    if (this.#phase === 'cancelling') return freeze({ kind: 'cancelling', queue, active: this.#active!, ...recovery });
   382	    if (this.#phase === 'completing') return freeze({ kind: 'completing', queue, active: this.#active!, ...recovery });
   383	    if (this.#active) return freeze({ kind: 'running', queue, active: this.#active, ...recovery });
   384	    return freeze({ kind: 'idle', queue, ...recovery });
   385	  }
   386	
   387	  async command(cmd: QueueCommand): Promise<QueueCommandResult> {
   388	    switch (cmd.kind) {
   389	      case 'submit':
   390	        return this.#submit(cmd);
   391	      case 'steer':
   392	        return this.#submit(cmd);
   393	      case 'cancel':
   394	        return this.#cancel();
   395	      case 'cancellation_settled': {
   396	        if (
   397	          this.#phase !== 'cancelling' ||
   398	          !this.#cancellationUnproven ||
   399	          this.#active?.executionId !== cmd.executionId ||
   400	          this.#cancellationExecutionId !== cmd.executionId
   401	        ) {
   402	          return { kind: 'no_op' };
   403	        }
   404	        this.#active = undefined;
   405	        this.#pendingAction = undefined;
   406	        this.#cancellationUnproven = false;
   407	        this.#cancellationExecutionId = null;
   408	        if (this.#cancelRetainedItemIds.size === 0) {
   409	          this.#phase = 'idle';
   410	          this.#pauseReason = undefined;
   411	        } else {
   412	          this.#phase = 'paused';
   413	          this.#pauseReason = 'manual';
   414	        }
   415	        this.#cancelRetainedItemIds.clear();
   416	        await this.#persist();
   417	        if (this.#phase === 'idle') await this.#dispatch();
   418	        return { kind: 'accepted' };
   419	      }
   420	      case 'answer_preflight': {
   421	        if (this.#phase !== 'awaiting_preflight') return { kind: 'rejected', reason: 'stale' };
   422	        const head = this.#queue[0]!;
   423	        if (head.id !== cmd.itemId || head.preflight?.actionId !== cmd.actionId) {
   424	          return { kind: 'rejected', reason: 'stale' };
   425	        }
   426	        if (!cmd.accepted) {
   427	          this.#queue.shift();
   428	          this.#phase = 'idle';
   429	          await this.#persist();
   430	          await this.#dispatch();
   431	          return { kind: 'accepted' };
   432	        }
   433	        return this.#acceptPreflight();
   434	      }
   435	      case 'resolve_tool_approval': {
   436	        if (this.#phase !== 'awaiting_active_action') return { kind: 'rejected', reason: 'stale' };
   437	        if (
   438	          this.#active!.executionId !== cmd.executionId ||
   439	          this.#pendingAction!.actionId !== cmd.actionId ||
   440	          this.#pendingAction!.kind !== 'tool_approval'
   441	        ) {
   442	          return { kind: 'rejected', reason: 'stale' };
   443	        }
   444	        return this.#resolveAction();
   445	      }
   446	      case 'answer_ask_user': {
   447	        if (this.#phase !== 'awaiting_active_action') return { kind: 'rejected', reason: 'stale' };
   448	        if (
   449	          this.#active!.executionId !== cmd.executionId ||
   450	          this.#pendingAction!.actionId !== cmd.actionId ||
   451	          this.#pendingAction!.kind !== 'ask_user'
   452	        ) {
   453	          return { kind: 'rejected', reason: 'stale' };
   454	        }
   455	        return this.#resolveAction();
   456	      }
   457	      case 'resume_queue':
   458	        if (this.#phase !== 'paused') return { kind: 'no_op' };
   459	        this.#phase = 'idle';
   460	        this.#pauseReason = undefined;
   461	        await this.#persist();
   462	        await this.#dispatch();
   463	        return { kind: 'accepted' };
   464	      case 'discard_queue':
   465	        this.#queue = [];
   466	        if (this.#phase === 'cancelling') {
   467	          // Discarding retained work during cancellation changes the stop's
   468	          // effective retention decision, but never releases active ownership.
   469	          this.#cancelRetainedItemIds.clear();
   470	        }
   471	        if (this.#phase === 'paused' && this.#queue.length === 0) {
   472	          this.#phase = 'idle';
   473	          this.#pauseReason = undefined;
   474	        }
   475	        await this.#persist();
   476	        return { kind: 'accepted' };
   477	      case 'edit_queued': {
   478	        const index = this.#queue.findIndex((item) => item.id === cmd.itemId);
   479	        if (index < 0 || !cmd.text.trim()) return { kind: 'rejected', reason: index < 0 ? 'not_queued' : 'invalid' };
   480	        this.#queue[index] = freeze({ ...this.#queue[index], text: cmd.text });
   481	        await this.#persist();
   482	        return { kind: 'accepted' };
   483	      }
   484	      case 'remove_queued': {
   485	        const index = this.#queue.findIndex((item) => item.id === cmd.itemId);
   486	        if (index < 0) return { kind: 'rejected', reason: 'not_queued' };
   487	        this.#queue.splice(index, 1);
   488	        if (this.#phase === 'cancelling') {
   489	          this.#cancelRetainedItemIds.delete(cmd.itemId);
   490	        }
   491	        if (this.#phase === 'awaiting_preflight' && index === 0) {
   492	          this.#phase = 'idle';
   493	        }
   494	        await this.#persist();
   495	        if (this.#phase === 'idle') {
   496	          await this.#dispatch();
   497	        }
   498	        return { kind: 'accepted' };
   499	      }
   500	      case 'change_execution_settings':
   501	      case 'change_cosmetic_settings':
   502	        await this.#persist();
   503	        return { kind: 'accepted' };
   504	    }
   505	  }
   506	
   507	  async #submit(cmd: Extract<QueueCommand, { kind: 'submit' | 'steer' }>): Promise<QueueCommandResult> {
   508	    if (!cmd.text.trim()) return { kind: 'rejected', reason: 'invalid' };
   509	    if (this.#queue.length >= this.#capacity) return { kind: 'rejected', reason: 'capacity' };
   510	    const id = cmd.id ?? this.#itemId();
   511	    if (!isNonEmptyString(id) || this.#queue.some((item) => item.id === id) || this.#active?.item.id === id) {
   512	      return { kind: 'rejected', reason: 'invalid' };
   513	    }
   514	    const item = freeze({
   515	      id: id as ItemId,
   516	      text: cmd.text,
   517	      sequence: this.#nextSequence++,
   518	      submittedAt: this.#now(),
   519	      ...(cmd.kind === 'steer' ? { steer: true as const } : {}),
   520	    });
   521	    if (cmd.kind === 'steer') {
   522	      // A steer that reaches the queue could not be delivered into the running
   523	      // turn, so it runs as its own turn — ahead of the follow-ups queued
   524	      // before it, which is the priority the user expressed by steering, and
   525	      // behind steers they sent earlier, which is the order they said it in.
   526	      const firstFollowUp = this.#queue.findIndex((queued) => !queued.steer);
   527	      const insertAt = firstFollowUp < 0 ? this.#queue.length : firstFollowUp;
   528	      this.#queue = [...this.#queue.slice(0, insertAt), item, ...this.#queue.slice(insertAt)].map((queued) =>
   529	        freeze({ ...queued, sequence: this.#nextSequence++ }),
   530	      );
   531	      await this.#persist();
   532	      await this.#dispatch();
   533	      return { kind: 'accepted' };
   534	    }
   535	    this.#queue.push(item);
   536	    await this.#persist();
   537	    await this.#dispatch();
   538	    return { kind: 'accepted' };
   539	  }
   540	
   541	  async event(event: TurnEvent<Terminal>): Promise<void> {
   542	    if (event.kind === 'tool_approval_requested' || event.kind === 'ask_user_requested') {
   543	      if (!this.#active || this.#active.executionId !== event.executionId || this.#phase !== 'running') return;
   544	      this.#pendingAction = {
   545	        actionId: event.actionId,
   546	        kind: event.kind === 'tool_approval_requested' ? 'tool_approval' : 'ask_user',
